define('mod_lamslesson/preview', ['exports', 'core/tree'], function(exports, Tree) {
    'use strict';

    Tree = Tree && Tree.default ? Tree.default : Tree;

    var SELECTORS = {
        tree: '#treeDiv',
        treeList: '#treeDiv ul[role="tree"]',
        sequence: 'input[name="sequence_id"]',
        name: 'input[name="name"]',
        previewButton: '#previewbutton',
        authorButton: '#authorbutton',
        refreshButton: '#refreshbutton'
    };

    var popupCenter = function(url, title, width, height) {
        var dualScreenLeft = window.screenLeft !== undefined ? window.screenLeft : window.screenX;
        var dualScreenTop = window.screenTop !== undefined ? window.screenTop : window.screenY;
        var viewportWidth = window.innerWidth ? window.innerWidth :
            document.documentElement.clientWidth ? document.documentElement.clientWidth : screen.width;
        var viewportHeight = window.innerHeight ? window.innerHeight :
            document.documentElement.clientHeight ? document.documentElement.clientHeight : screen.height;
        var left = ((viewportWidth / 2) - (width / 2)) + dualScreenLeft;
        var top = ((viewportHeight / 2) - (height / 2)) + dualScreenTop;
        var newWindow = window.open(
            url,
            title,
            'scrollbars=yes, width=' + width + ', height=' + height + ', top=' + top + ', left=' + left
        );

        if (newWindow && window.focus) {
            newWindow.focus();
        }
    };

    var setPreviewVisibility = function(visible) {
        var button = document.querySelector(SELECTORS.previewButton);
        if (button) {
            button.style.visibility = visible ? 'visible' : 'hidden';
        }
    };

    var selectSequence = function(id, name) {
        var sequenceInput = document.querySelector(SELECTORS.sequence);
        if (!sequenceInput) {
            return;
        }

        sequenceInput.value = id;

        var isSequence = id !== undefined && id !== null && id !== '' && id !== '0';
        if (isSequence) {
            var nameInput = document.querySelector(SELECTORS.name);
            if (nameInput && nameInput.value === '') {
                nameInput.value = name;
            }
            setPreviewVisibility(true);
        } else {
            setPreviewVisibility(false);
        }
    };

    var renderNode = function(node) {
        var item = document.createElement('li');
        item.setAttribute('role', 'treeitem');
        item.dataset.id = node.id !== undefined && node.id !== null ? node.id : 0;
        item.dataset.label = node.label !== undefined && node.label !== null ? node.label : '';

        var label = document.createElement('p');
        label.textContent = node.label !== undefined && node.label !== null ? node.label : '';
        item.appendChild(label);

        if (Array.isArray(node.children) && node.children.length > 0) {
            var expanded = node.expanded !== false;
            item.setAttribute('aria-expanded', expanded ? 'true' : 'false');

            var group = document.createElement('ul');
            group.setAttribute('role', 'group');
            if (!expanded) {
                group.setAttribute('aria-hidden', 'true');
            }

            node.children.forEach(function(child) {
                group.appendChild(renderNode(child));
            });
            item.appendChild(group);
        }

        return item;
    };

    var renderTree = function(container, nodes) {
        var list = document.createElement('ul');
        list.className = 'foldertree';
        list.setAttribute('role', 'tree');
        nodes.forEach(function(node) {
            list.appendChild(renderNode(node));
        });
        container.appendChild(list);
    };

    var openPreview = function(config) {
        var sequenceInput = document.querySelector(SELECTORS.sequence);
        var sequenceId = sequenceInput ? sequenceInput.value : '';
        var url = config.previewUrl +
            '&ldId=' + encodeURIComponent(sequenceId) +
            '&course=' + encodeURIComponent(config.course);

        popupCenter(url, 'preview', 1280, 720);
    };

    var init = function() {
        var container = document.querySelector(SELECTORS.tree);
        if (!container) {
            return;
        }

        var sequences = [];
        try {
            sequences = JSON.parse(container.dataset.sequences || '[]');
        } catch (error) {
            sequences = [];
        }

        renderTree(container, sequences);

        var config = {
            course: container.dataset.course,
            previewUrl: container.dataset.previewUrl
        };

        var sequenceInput = document.querySelector(SELECTORS.sequence);
        setPreviewVisibility(sequenceInput && sequenceInput.value !== '' && sequenceInput.value !== '0');

        if (container.querySelector('ul[role="tree"]')) {
            new Tree(SELECTORS.treeList, function(item) {
                var node = item[0];
                var id = node ? node.dataset.id : '';
                if (id !== undefined && id !== '' && id !== '0') {
                    selectSequence(id, node.dataset.label);
                }
            });
        }

        var previewButton = document.querySelector(SELECTORS.previewButton);
        if (previewButton) {
            previewButton.addEventListener('click', function(event) {
                event.preventDefault();
                openPreview(config);
            });
        }

        var authorButton = document.querySelector(SELECTORS.authorButton);
        if (authorButton) {
            authorButton.addEventListener('click', function(event) {
                event.preventDefault();
                popupCenter(authorButton.dataset.url, 'author', 1280, 720);
            });
        }

        var refreshButton = document.querySelector(SELECTORS.refreshButton);
        if (refreshButton) {
            refreshButton.addEventListener('click', function(event) {
                event.preventDefault();
                window.location.reload();
            });
        }
    };

    exports.init = init;
});
